80	void MergeTreeReaderWide::prefetchBeginOfRange(Priority priority)
81	{
82	    prefetched_streams.clear();
83	
84	    if (all_mark_ranges.getNumberOfMarks() == 0)
85	        return;
86	
87	    try
88	    {
89	        /// Start prefetches for all columns. But don't deserialize prefixes, because it can be a heavy operation
90	        /// (for example for JSON column) and starting prefetches for all subcolumns here can consume a lot of memory.
91	        prefetchForAllColumns(priority, columns_to_read.size(), all_mark_ranges.front().begin, all_mark_ranges.back().end, false, /*deserialize_prefixes=*/false);
92	        prefetched_from_mark = all_mark_ranges.front().begin;
93	        /// Arguments explanation:
94	        /// Current prefetch is done for read tasks before they can be picked by reading threads in IMergeTreeReadPool::getTask method.
95	        /// 1. columns_to_read.size() == requested_columns.size() == readRows::res_columns.size().
96	        /// 3. current_task_last_mark argument in readRows() (which is used only for reading from remote fs to make precise
97	        /// ranged read requests) is different from current reader's IMergeTreeReader::all_mark_ranges.back().end because
98	        /// the same reader can be reused between read tasks - if the new task mark ranges correspond to the same part we last
99	        /// read, so we cannot rely on all_mark_ranges and pass actual current_task_last_mark. But here we can do prefetch for begin
100	        /// of range only once so there is no such problem.
101	        /// 4. continue_reading == false, as we haven't read anything yet.
102	    }
103	    catch (...)
104	    {
105	        if (!isRetryableException(std::current_exception()))
106	            data_part_info_for_read->reportBroken();
107	        throw;
108	    }
109	}
