111	void MergeTreeReaderWide::prefetchForAllColumns(
112	    Priority priority,
113	    size_t num_columns,
114	    size_t from_mark,
115	    size_t current_task_last_mark,
116	    bool continue_reading,
117	    bool deserialize_prefixes)
118	{
119	    bool do_prefetch = data_part_info_for_read->getDataPartStorage()->isStoredOnRemoteDisk()
120	        ? settings.read_settings.remote_fs_prefetch
121	        : settings.read_settings.local_fs_prefetch;
122	
123	    if (!do_prefetch || all_mark_ranges.getNumberOfMarks() == 0)
124	        return;
125	    if (settings.filesystem_prefetches_limit && num_columns > settings.filesystem_prefetches_limit)
126	        return;
127	
128	    if (deserialize_prefixes)
129	        deserializePrefixForAllColumnsWithPrefetch(num_columns, from_mark, current_task_last_mark, priority);
130	
131	    /// Request reading of data in advance,
132	    /// so if reading can be asynchronous, it will also be performed in parallel for all columns.
133	    for (size_t pos = 0; pos < num_columns; ++pos)
134	    {
135	        if (isColumnDroppedByPendingMutation(pos))
136	            continue;
137	
138	        try
139	        {
140	            auto & cache = caches[columns_to_read[pos].getNameInStorage()];
141	            prefetchForColumn(
142	                priority, columns_to_read[pos], serializations[pos], from_mark, continue_reading,
143	                current_task_last_mark, cache);
144	        }
145	        catch (Exception & e)
146	        {
147	            /// Better diagnostics.
148	            e.addMessage("(while reading column " + columns_to_read[pos].name + ")");
149	            throw;
150	        }
151	    }
152	}
