62	void SerializationLowCardinality::enumerateStreams(
63	    EnumerateStreamsSettings & settings,
64	    const StreamCallback & callback,
65	    const SubstreamData & data) const
66	{
67	    const auto * column_lc = data.column ? &getColumnLowCardinality(*data.column) : nullptr;
68	
69	    if (settings.use_specialized_prefixes_and_suffixes_substreams)
70	    {
71	        settings.path.push_back(Substream::DictionaryKeysPrefix);
72	        callback(settings.path);
73	        settings.path.pop_back();
74	    }
75	
76	    settings.path.push_back(Substream::DictionaryKeys);
77	    auto dict_data = SubstreamData(dict_inner_serialization)
78	        .withType(data.type ? dictionary_type : nullptr)
79	        .withColumn(column_lc ? column_lc->getDictionary().getNestedColumn() : nullptr)
80	        .withSerializationInfo(data.serialization_info);
81	
82	    settings.path.back().data = dict_data;
83	    callback(settings.path);
84	
85	    settings.path.back() = Substream::DictionaryIndexes;
86	    settings.path.back().data = data;
87	
88	    callback(settings.path);
89	    settings.path.pop_back();
90	}
