217	void MergeTreeReaderStream::adjustRightMark(size_t right_mark)
218	{
219	    /**
220	     * Note: this method is called multiple times for the same range of marks -- each time we
221	     * read from stream, but we must update last_right_offset only if it is bigger than
222	     * the last one to avoid redundantly cancelling prefetches.
223	     */
224	    init();
225	    auto right_offset = getRightOffset(right_mark);
226	
227	    if (!right_offset)
228	    {
229	        if (last_right_offset && *last_right_offset == 0)
230	            return;
231	
232	        last_right_offset = 0; // Zero value means the end of file.
233	        data_buffer->setReadUntilEnd();
234	    }
235	    else
236	    {
237	        if (last_right_offset && right_offset <= last_right_offset.value())
238	            return;
239	
240	        last_right_offset = right_offset;
241	        data_buffer->setReadUntilPosition(right_offset);
242	    }
243	}
