251	size_t MergeTreeReaderStreamSingleColumn::getRightOffset(size_t right_mark)
252	{
253	    /// NOTE: if we are reading the whole file, then right_mark == marks_count
254	    /// and we will use max_read_buffer_size for buffer size, thus avoiding the need to load marks.
255	
256	    /// Special case, can happen in Collapsing/Replacing engines
257	    if (marks_count == 0)
258	        return 0;
259	
260	    chassert(right_mark <= marks_count);
261	    loadMarks();
262	
263	    if (right_mark == 0)
264	        return marks_getter->getMark(right_mark, 0).offset_in_compressed_file;
265	
266	    if (right_mark == marks_count)
267	        return file_size;
268	
269	    /// Find the right border of the last mark we need to read.
270	    /// To do that let's find the upper bound of the offset of the last
271	    /// included mark.
272	
273	    if (settings.is_low_cardinality_dictionary)
274	    {
275	        /// In LowCardinality dictionary several consecutive marks can point to the same offset.
276	        ///
277	        /// Also, in some cases, when one granule is not-atomically written (which is possible at merges)
278	        /// one granule may require reading of two dictionaries which starts from different marks.
279	        /// The only correct way is to take offset from at least next different granule from the right one.
280	        /// So, that's why we have to read one extra granule to the right,
281	        /// while reading dictionary of LowCardinality.
282	        ///
283	        /// Example:
284	        /// Mark 0, points to [0, 8]
285	        /// Mark 1, points to [0, 8]
286	        /// Mark 2, points to [0, 8]
287	        /// Mark 3, points to [0, 8]
288	        /// Mark 4, points to [42336, 2255]
289	        /// Mark 5, points to [42336, 2255]  <--- for example need to read until 5
290	        /// Mark 6, points to [42336, 2255]  <--- not suitable, because have same offset
291	        /// Mark 7, points to [84995, 7738]  <--- next different mark
292	        /// Mark 8, points to [84995, 7738]
293	        /// Mark 9, points to [126531, 8637] <--- what we are looking for
294	
295	        auto indices = collections::range(right_mark, marks_count);
296	        auto next_different_mark = [&](auto lhs, auto rhs)
297	        {
298	            return marks_getter->getMark(lhs, 0).asTuple() < marks_getter->getMark(rhs, 0).asTuple();
299	        };
300	
301	        auto it = std::upper_bound(indices.begin(), indices.end(), right_mark, std::move(next_different_mark));
302	        if (it == indices.end())
303	            return file_size;
304	
305	        right_mark = *it;
306	    }
307	
308	    /// Special case for streams with dynamic/object structure.
309	    /// It consists of 2 parts of data - during the serialization the first part is written before the data and second - after the data.
310	    /// But during deserialization we read both parts before the data, so we can't use the marks and need to always return the
311	    /// whole file size.
312	    if (settings.is_metadata_file)
313	        return file_size;
314	
315	    /// This is a good scenario. The compressed block is finished within the right mark,
316	    /// and previous mark was different.
317	    if (marks_getter->getMark(right_mark, 0).offset_in_decompressed_block == 0
318	        && marks_getter->getMark(right_mark, 0) != marks_getter->getMark(right_mark - 1, 0))
319	        return marks_getter->getMark(right_mark, 0).offset_in_compressed_file;
320	
321	    /// If right_mark has non-zero offset in decompressed block, we have to
322	    /// read its compressed block in a whole, because it may consist of data from previous granule.
323	    ///
324	    /// For example:
325	    /// Mark 6, points to [42336, 2255]
326	    /// Mark 7, points to [84995, 7738]  <--- right_mark
327	    /// Mark 8, points to [84995, 7738]
328	    /// Mark 9, points to [126531, 8637] <--- what we are looking for
329	    ///
330	    /// Since mark 7 starts from offset in decompressed block 7738,
331	    /// it has some data from mark 6 and we have to read
332	    /// compressed block  [84995; 126531 in a whole.
333	
334	    auto indices = collections::range(right_mark, marks_count);
335	    auto next_different_compressed_offset = [&](auto lhs, auto rhs)
336	    {
337	        return marks_getter->getMark(lhs, 0).offset_in_compressed_file < marks_getter->getMark(rhs, 0).offset_in_compressed_file;
338	    };
339	
340	    auto it = std::upper_bound(indices.begin(), indices.end(), right_mark, std::move(next_different_compressed_offset));
341	    if (it != indices.end())
342	        return marks_getter->getMark(*it, 0).offset_in_compressed_file;
343	
344	    return file_size;
345	}
