347	std::pair<size_t, size_t> MergeTreeReaderStreamSingleColumn::estimateMarkRangeBytes(const MarkRanges & mark_ranges)
348	{
349	    loadMarks();
350	
351	    size_t max_range_bytes = 0;
352	    size_t sum_range_bytes = 0;
353	
354	    for (const auto & mark_range : mark_ranges)
355	    {
356	        size_t left_mark = mark_range.begin;
357	        size_t right_mark = mark_range.end;
358	        size_t left_offset = left_mark < marks_count ? marks_getter->getMark(left_mark, 0).offset_in_compressed_file : 0;
359	        auto mark_range_bytes = getRightOffset(right_mark) - left_offset;
360	
361	        max_range_bytes = std::max(max_range_bytes, mark_range_bytes);
362	        sum_range_bytes += mark_range_bytes;
363	    }
364	
365	    return {max_range_bytes, sum_range_bytes};
366	}
